-- 1. 조회: 지금 들어 있는 MS레벨 DT 정답키 (몇 개·몇 문항인지 확인)
select id, level, num_q, updated_at from exam_keys where test_type='DT' and upper(level) in ('MSA1','MSA2','MSB1','MSB2') order by level;

-- 2. 백업 (되돌리기용 — 아래 되돌리기 SQL 참고)
create table if not exists exam_keys_backup_ms_20261112 as
  select * from exam_keys where test_type='DT' and upper(level) in ('MSA1','MSA2','MSB1','MSB2');

